      /* Kaşgarlı'nın yuvarlak haritası */
      s += '<g transform="translate(220 480)"><rect x="-100" y="-100" width="200" height="200" fill="#6a4a24"/><rect x="-90" y="-90" width="180" height="180" fill="#e8dcc0"/><circle r="78" fill="#d8c8a0" stroke="#8a6a3a" stroke-width="3"/><circle r="78" fill="none" stroke="#6a9ac8" stroke-width="8" opacity=".5"/><path d="M-40 -30C-10 -50 30 -40 50 -10C40 20 10 40 -20 30C-40 20 -50 0 -40 -30Z" fill="#b8a878"/><circle cx="4" cy="-6" r="5" fill="#a8302a"/></g>';
