        [0, 1, 2, 3, 4, 5].map(function (r) { return '<path d="M-100 ' + (-200 + r * 12) + 'h' + (180 - r * 6) + '" stroke="#8a8a92" stroke-width="3" stroke-dasharray="4 3"/>'; }).join("") + [0, 1, 2, 3, 4].map(function (r) { return '<path d="M-104 ' + (-120 + r * 10) + 'h208" stroke="#7a7a82" stroke-width="2" stroke-dasharray="2 2"/>'; }).join("") + [0, 1, 2, 3, 4].map(function (r) { return '<path d="M-106 ' + (-60 + r * 11) + 'h212" stroke="#9a9aa2" stroke-width="2" stroke-dasharray="6 2 2 2"/>'; }).join("") +
        '<ellipse cx="-30" cy="-190" rx="22" ry="8" fill="none" stroke="#e8c870" stroke-width="2"/></g>';
      /* palmiye yaprağı el yazması (vitrin) */
