      var t = '<g transform="scale(1 .32) rotate(45)">'; for (var i = 0; i < 6; i++) for (var j = 0; j < 6; j++) t += '<rect x="' + (i * 10 - 30) + '" y="' + (j * 10 - 30) + '" width="10" height="10" fill="' + ((i + j) % 2 ? "#2a1a10" : "#e8dcc0") + '"/>';
      s += t + '</g><path d="M-10 -4v-16h4v-6h8v6h4v16Z" fill="#e8dcc0"/><circle cx="16" cy="-14" r="6" fill="#1a1010"/><path d="M12 -2l1 -10h6l1 10Z" fill="#1a1010"/></g>';
