      [[187, 310], [415, 340]].forEach(function (b, i) { s += '<g class="duman" style="animation-delay:-' + i * 1.5 + 's"><circle cx="' + b[0] + '" cy="' + (b[1] - 20) + '" r="22" fill="#6a5a5a" opacity=".45"/><circle cx="' + (b[0] + 24) + '" cy="' + (b[1] - 50) + '" r="30" fill="#6a5a5a" opacity=".3"/></g>'; });
      for (var w = 0; w < 6; w++) s += '<rect x="' + (150 + w * 55) + '" y="500" width="30" height="40" fill="#ffc870" opacity="' + (0.4 + (w % 3) * 0.2) + '"/>';
