      s += '<path d="M0 680H1600V700H0Z" fill="#4a3a36"/><path d="M200 700Q400 780 600 700M600 700Q800 780 1000 700M1000 700Q1200 780 1400 700" stroke="#4a3a36" stroke-width="14" fill="none"/>';
      for (var p = 0; p < 22; p++) { var x = 60 + p * 32 + (p % 3) * 6, hh = 34 + (p % 4) * 4; s += '<g class="yuz" style="--s:' + (3 + (p % 5)) + 's"><rect x="' + x + '" y="' + (680 - hh) + '" width="12" height="' + (hh - 10) + '" rx="4" fill="#1a1216"/><circle cx="' + (x + 6) + '" cy="' + (680 - hh - 4) + '" r="6" fill="#1a1216"/></g>'; }
      /* sandık ve kiosk */
